def check_expression(expr: str) -> bool:
    """
    Check if the given expression is balanced.
    A balanced expression has matching pairs of brackets: (), [], and {}.
    """
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}

    for char in expr:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map:
            if not stack:
                return False
            if stack.pop() != bracket_map[char]:
                return False

    return len(stack) == 0
