import heapq

def larg_nnum(dataset, n):
    """
    Returns a list of the n largest items from the dataset in descending order.

    Args:
        dataset (list): A list of comparable items (e.g., numbers).
        n (int): The number of largest items to return.

    Returns:
        list: A list containing the n largest items in descending order.
    """
    if n <= 0:
        return []
    if n >= len(dataset):
        return sorted(dataset, reverse=True)

    # Use a min-heap of size n to keep track of the n largest elements
    heap = []
    for i, num in enumerate(dataset):
        if len(heap) < n:
            heapq.heappush(heap, num)
        else:
            if num > heap[0]:
                heapq.heapreplace(heap, num)

    # Return the n largest elements in descending order
    return sorted(heap, reverse=True)

