def is_samepatterns(patterns: list, sequences: list) -> bool:
    """
    Check if the sequences follow the pattern defined by the patterns array.

    Each element in patterns must map to exactly one element in sequences,
    and vice versa (bijection).

    Args:
        patterns: List of pattern strings (e.g., ["a", "b", "b"])
        sequences: List of sequence strings (e.g., ["red", "green", "green"])

    Returns:
        True if the sequences follow the pattern, False otherwise.
    """
    if len(patterns) != len(sequences):
        return False

    pattern_to_sequence = {}
    sequence_to_pattern = {}

    for p, s in zip(patterns, sequences):
        if p in pattern_to_sequence:
            if pattern_to_sequence[p] != s:
