from typing import List, Any

def check_subset_list(subset_list: List[Any], superset_list: List[Any]) -> bool:
    """
    Check if a nested list is a subset of another nested list.

    A list A is a subset of list B if every element in A (including nested elements)
    can be found in B at the same structural level. This means:
    - If an element in A is a list, it must be a sub-list of a corresponding list in B.
    - If an element in A is not a list, it must be present in B.

    The function returns True if the subset_list is a valid subset of superset_list,
    and False otherwise.
    """
    def is_element_subset(element: Any, superset: List[Any]) -> bool:
        if isinstance(element, list):
            # If element is a list, it must be a sub-list of some list in superset
            for sup in superset:
                if is_list_subset(element, sup):
                    return True
            return False
        else:
            # If element is not a list, check if it exists in superset
            return element in superset

    def is_list_subset(sub: List[Any], sup: List[Any]) -> bool:
        # Check if sub is a sub-list of sup
        # This means every element in sub must be in sup
        for item in sub:
            if not is_element_subset(item, sup):
                return False
        return True

    # Check if every element in subset_list is a subset of superset_list
    for item in subset_list:
        if not is_element_subset(item, superset_list):
            return False
    return True
